#
# Version script for the interposer. Each symbol MUST sit in the same version
# node the real libamdhip64 assigns it, or a versioned reference from the
# application will not bind to our definition and the interposition silently
# does nothing. Tags here were taken from `readelf --dyn-syms` on the shipped
# runtime, not from the header or from guesswork.

hip_4.2 {
    global:
        __hipRegisterFatBinary;
        __hipRegisterFunction;
        hipLaunchKernel;
        hipModuleGetFunction;
        hipModuleLaunchKernel;
        hipModuleLoadData;
        hipModuleLoadDataEx;
        hipModuleUnload;
};

